/* M4 host: boot hook, config-page toggles and their settings file. See include/m4/pk_host.h.
 *
 * The toggles and settings live in their own file, system/mods.json, loaded right after the firmware's
 * system/device.json and saved whenever the firmware saves it, so device.json stays
 * exactly stock (delete mods.json and every mod setting is back to off). */
#include <stdint.h>
#include "pk_host.h"

#define PK_HOST_MAGIC   0x54534f48u     /* 'HOST' */
#define LED_ON          0x80

typedef struct {
    uint8_t key;
    uint8_t *var;
} pk_toggle_t;

/* generated by m4host.py (gen/pk_host_gen.c) */
extern const pk_toggle_t pk_toggles[];
extern const int pk_n_toggles;
extern const fw_json_schema_t pk_mods_schema;    /* entries hold absolute addresses */
void pk_host_run_inits(void);
void pk_host_run_savers(void);

#define PK_MODS_JSON "system/mods.json"

extern uint32_t __pk_bss_start[], __pk_bss_end[], __pk_axi_start[], __pk_axi_end[];
static uint32_t magic;

int pk_host_booted(void)
{
    return magic == PK_HOST_MAGIC;
}

/* replaces boot_init's call to config_files_init */
void pk4_boot(void)
{
    for (uint32_t *p = __pk_bss_start; p < __pk_bss_end; p++)
        *p = 0;
    for (uint32_t *p = __pk_axi_start; p < __pk_axi_end; p++)
        *p = 0;
    magic = PK_HOST_MAGIC;
    pk_host_run_inits();
    fw_config_files_init();             /* loads system/device.json (stock) */
    if (pk_mods_schema.count)
        fw_json_load(PK_MODS_JSON, &pk_mods_schema, (void *)0);
}

/* replaces the firmware's tail calls to device_json_save */
void pk4_device_json_save(void)
{
    fw_device_json_save();
    if (pk_mods_schema.count)
        fw_json_save(PK_MODS_JSON, &pk_mods_schema, (const void *)0);
    pk_host_run_savers();
}

int pk4_cfg_event(const uint8_t *evt)
{
    if (evt[1] == CONST_cfg_key_event) {
        for (int i = 0; i < pk_n_toggles; i++) {
            if (evt[0] == pk_toggles[i].key) {
                *pk_toggles[i].var ^= 1;
                FW_CFG_DIRTY = 1;       /* saved (mods.json) on page exit */
                return 1;
            }
        }
    }
    return fw_cfg_event(evt);
}

void pk4_cfg_render(void *a, void *b, void *c, void *d)
{
    fw_cfg_render(a, b, c, d);
    for (int i = 0; i < pk_n_toggles; i++)
        fw_set_led(pk_toggles[i].key, *pk_toggles[i].var ? LED_ON : 0);
}
